using System;using System.Linq;using System.Reflection;using UnityEngine;
public static class AbortDetailedPlay {public static object Main(string reason){var t=AppDomain.CurrentDomain.GetAssemblies().SelectMany(a=>new[]{a.GetType("Chapters45Playtest"),a.GetType("Chapters45DetailedPlaytest")}).Where(x=>x!=null).First(x=>(bool)x.GetField("active",BindingFlags.Static|BindingFlags.NonPublic).GetValue(null));var d=UnityEngine.Object.FindFirstObjectByType<Chapter45Director>();var evidence=new{d.CurrentFloor,d.Distance,targets=d.targets.Select(x=>new{x.name,x.floor,active=x.gameObject.activeInHierarchy,x.Open}).ToArray(),reason};t.GetMethod("Finish",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{reason});return evidence;}}
